import type { FailureReasonCode } from './failureReason';

export type DevServerFailureReason =
  | 'spawn_error'
  | 'exited'
  | 'timeout'
  | 'missing_dev_script'
  | 'compile_error'
  | 'dependency_install_failed';

const COMPILATION_FAILURE_PATTERN =
  /Failed to compile|Module parse failed|TurbopackInternalError|Error evaluating Node\.js code|Transform failed with \d+ errors?/i;

export const isCompilationFailureOutput = (output: string): boolean =>
  COMPILATION_FAILURE_PATTERN.test(output);

const PORT_IN_USE_RE =
  /EADDRINUSE|address already in use|already running|already in use/i;

export function isPortInUseOutput(output: string): boolean {
  return PORT_IN_USE_RE.test(output);
}

const MISSING_DEPENDENCY_RE =
  /Cannot find module|Cannot find package|ERR_MODULE_NOT_FOUND|MODULE_NOT_FOUND|command not found|(?:sh|bash|zsh)(?::| -c:)? (?:line \d+: )?[^\n]*: not found/i;

export function isMissingDependencyOutput(output: string): boolean {
  return MISSING_DEPENDENCY_RE.test(output);
}

export class DevServerStartError extends Error {
  readonly reason: DevServerFailureReason;
  readonly portInUse: boolean;
  readonly detail: string;
  readonly exitCode: number | null;
  readonly signal: NodeJS.Signals | null;
  readonly reasonCode?: FailureReasonCode;
  readonly summary?: string;

  constructor(opts: {
    message: string;
    reason: DevServerFailureReason;
    portInUse: boolean;
    detail: string;
    exitCode?: number | null;
    signal?: NodeJS.Signals | null;
    reasonCode?: FailureReasonCode;
    summary?: string;
  }) {
    super(opts.message);
    this.name = 'DevServerStartError';
    this.reason = opts.reason;
    this.portInUse = opts.portInUse;
    this.detail = opts.detail;
    this.exitCode = opts.exitCode ?? null;
    this.signal = opts.signal ?? null;
    this.reasonCode = opts.reasonCode;
    this.summary = opts.summary;
  }
}

export function isDevServerStartError(
  err: unknown,
): err is DevServerStartError {
  return err instanceof DevServerStartError;
}
